def cmp_semver(a, b):
    def parse(version):
        # Handle build metadata (ignored)
        if '+' in version:
            version = version.split('+', 1)[0]
        # Handle pre-release identifiers
        if '-' in version:
            return version.split('-', 1)
        else:
            return version, None

    base_a, pre_a = parse(a)
    base_b, pre_b = parse(b)

    # 1. Compare major, minor, patch numerically
    parts_a = list(map(int, base_a.split('.')))
    parts_b = list(map(int, base_b.split('.')))

    for p_a, p_b in zip(parts_a, parts_b):
        if p_a < p_b:
            return -1
        if p_a > p_b:
            return 1

    # 2. Compare pre-release
    # A version WITH pre-release sorts BEFORE the same version WITHOUT one
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1 # a is higher
    if pre_b is None:
        return -1 # a is lower

    ids_a = pre_a.split('.')
    ids_b = pre_b.split('.')

    len_a, len_b = len(ids_a), len(ids_b)

    for i in range(max(len_a, len_b)):
        id_a = ids_a[i] if i < len_a else None
        id_b = ids_b[i] if i < len_b else None

        if id_a is None:
            return -1 # a has fewer identifiers
        if id_b is None:
            return 1  # b has fewer identifiers

        is_num_a = id_a.isdigit()
        is_num_b = id_b.isdigit()

        if is_num_a and is_num_b:
            n_a, n_b = int(id_a), int(id_b)
            if n_a < n_b:
                return -1
            if n_a > n_b:
                return 1
        elif not is_num_a and not is_num_b:
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1
        else:
            # Numeric < Alphanumeric
            if is_num_a:
                return -1
            else:
                return 1

    return 0
