from typing import List, Tuple, Optional

def parse_range(header: str, size: int) -> Optional[List[Tuple[int, int]]]:
    # Reject non‑bytes units and missing prefix
    if not header.startswith("bytes="):
        return None

    ranges_str = header[6:].strip()
    if not ranges_str:
        return None

    parts = ranges_str.split(',')
    result = []

    for part in parts:
        if not part:
            return None  # empty part due to stray comma

        if '-' in part:
            left, right = part.split('-', 1)
            left = left.strip()
            right = right.strip()

            # Handle invalid both‑empty case (e.g. "-" alone)
            if not left and not right:
                return None

            # Suffix range: "-suffix"
            if not left:
                if not right.isdigit():
                    return None
                suffix = int(right)
                if suffix < 0:
                    return None
                if suffix == 0:
                    continue  # unsatisfiable
                if suffix > size:
                    start = 0
                    end = size - 1
                else:
                    start = size - suffix
                    end = size - 1
                if start > end:
                    continue  # unsatisfiable (e.g. size == 0)
                result.append((start, end))

            # Prefix range: "start-"
            elif not right:
                if not left.isdigit():
                    return None
                start = int(left)
                if start < 0:
                    return None
                if start >= size:
                    continue  # unsatisfiable
                end = size - 1
                result.append((start, end))

            # Exact range: "start-end"
            else:
                if not left.isdigit() or not right.isdigit():
                    return None
                start = int(left)
                end = int(right)
                if start < 0 or end < 0:
                    return None
                if start > end:
                    return None  # malformed
                if start >= size:
                    continue  # unsatisfiable
                if end >= size:
                    end = size - 1
                if start <= end:
                    result.append((start, end))
        else:
            return None  # no hyphen means invalid format

    # No satisfiable ranges remain
    if not result:
        return None
    return result
